package com.group01.assessment.application.usecase;
import com.group01.assessment.application.result.GradingJobResult; import com.group01.assessment.domain.exception.*; import com.group01.assessment.domain.repository.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.util.UUID;
@Service public class GetGradingJobUseCase { private final GradingJobRepository jobs; public GetGradingJobUseCase(GradingJobRepository jobs){this.jobs=jobs;} @Transactional(readOnly=true) public GradingJobResult execute(UUID userId,UUID id){var j=jobs.findById(id).orElseThrow(()->new AssessmentNotFoundException("Grading job not found")); if(!j.userId().equals(userId)) throw new AssessmentAccessDeniedException("Grading job does not belong to current user"); return new GradingJobResult(j.id(),j.submissionId(),j.userId(),j.skill(),j.gradingMode(),j.status(),j.pointCostSnapshot(),j.idempotencyKey(),j.createdAt(),j.completedAt());} }
